"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["72162"],{46969(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.formatos_permitidos.formato_invalido","status":422,"titulo":"Formato n\xe3o reconhecido"},"descricao":{"codigo":"uniplus.selecao.formatos_permitidos.formato_invalido","requisitos":[],"oQueAconteceu":["Os formatos de arquivo que uma exig\xeancia pode aceitar s\xe3o `PDF`, `JPEG` e `PNG`, com a grafia\\nexata em mai\xfasculas. Um item da lista de formatos permitidos trouxe outro formato. A mensagem de\\ndetalhe identifica o formato recusado.","A confer\xeancia acontece na montagem de cada exig\xeancia, depois das confer\xeancias do tipo de\\ndocumento, das condi\xe7\xf5es e das bases legais, e depois da idade m\xe1xima de emiss\xe3o; a do modelo\\ncitado vem em seguida. A confer\xeancia registra as recusas das regras informadas, e a lista de\\nformatos para na primeira entrada com defeito, que \xe9 conferida nesta ordem: formato reconhecido,\\nformato sem repeti\xe7\xe3o\\n([`formato_duplicado`](/erros/uniplus.selecao.formatos_permitidos.formato_duplicado)) e limite por\\nformato positivo\\n([`tamanho_maximo_bytes_max_invalido`](/erros/uniplus.selecao.formatos_permitidos.tamanho_maximo_bytes_max_invalido)).","Esta mesma confer\xeancia \xe9 refeita quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada: em toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios,\\nas opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho da p\xe1gina).\\nPelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz formato desconhecido,\\nporque a defini\xe7\xe3o o recusa antes. Nessas leituras a recusa se refere \xe0 vers\xe3o congelada, n\xe3o ao\\npedido enviado."],"comoResolver":["Troque o formato recusado por um dos formatos reconhecidos (`PDF`, `JPEG` ou `PNG`) ou, se qualquer\\nformato \xe9 aceito, declare `formatosPermitidos` como o texto `QUALQUER`. Depois, envie a defini\xe7\xe3o\\nde novo.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema\\nrecusou a configura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir os documentos exigidos do\\nprocesso n\xe3o a corrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Formatos permitidos"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);